-- M0-T6: outbox relay (ADR-011) + consumer idempotency.
--
-- processed_events: tenant isolation generated by tenantRlsSql (packages/db/src/rls.ts).
-- Append-only for app_user (SELECT, INSERT): a processed event is never "unprocessed".
ALTER TABLE "processed_events" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
ALTER TABLE "processed_events" FORCE ROW LEVEL SECURITY;
--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "processed_events" AS PERMISSIVE FOR ALL TO PUBLIC USING ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid) WITH CHECK ("tenant_id" = nullif(current_setting('app.tenant_id', true), '')::uuid);
--> statement-breakpoint
REVOKE ALL ON "processed_events" FROM "app_user";
--> statement-breakpoint
GRANT SELECT, INSERT ON "processed_events" TO "app_user";
--> statement-breakpoint

-- The relay reads unpublished events of EVERY tenant. outbox_events is FORCE RLS, which binds the
-- owner too, so the SECURITY DEFINER functions below (running as the owner) would see nothing.
-- These two policies apply ONLY to the role running this migration (the owner: revops_owner
-- locally/CI, neondb_owner on Neon) — never to app_user, whose only way in is the functions.
-- The catalog meta-test asserts exactly that.
CREATE POLICY "outbox_relay_select" ON "outbox_events" AS PERMISSIVE FOR SELECT TO CURRENT_USER USING (true);
--> statement-breakpoint
CREATE POLICY "outbox_relay_update" ON "outbox_events" AS PERMISSIVE FOR UPDATE TO CURRENT_USER USING (true) WITH CHECK (true);
--> statement-breakpoint

-- Claims up to p_limit unpublished events, oldest first, locking them for the CALLER'S transaction
-- (FOR UPDATE SKIP LOCKED): a concurrent relay skips them instead of publishing them twice. The
-- caller enqueues the jobs and calls outbox_mark_published in that same transaction.
CREATE FUNCTION "outbox_claim_batch"(p_limit integer)
RETURNS TABLE (
  id uuid, tenant_id uuid, type text, aggregate_id uuid, payload jsonb, occurred_at timestamptz
)
LANGUAGE sql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
  SELECT o.id, o.tenant_id, o.type, o.aggregate_id, o.payload, o.occurred_at
  FROM outbox_events o
  WHERE o.published_at IS NULL
  ORDER BY o.occurred_at, o.id
  LIMIT least(greatest(coalesce(p_limit, 1), 1), 500)
  FOR UPDATE SKIP LOCKED
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "outbox_claim_batch"(integer) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "outbox_claim_batch"(integer) TO "app_user";
--> statement-breakpoint

-- Marks claimed events published. Only rows still unpublished change; returns how many did.
CREATE FUNCTION "outbox_mark_published"(p_ids uuid[], p_now timestamptz)
RETURNS integer
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE outbox_events SET published_at = p_now
  WHERE id = ANY (p_ids) AND published_at IS NULL;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "outbox_mark_published"(uuid[], timestamptz) FROM PUBLIC;
--> statement-breakpoint
GRANT EXECUTE ON FUNCTION "outbox_mark_published"(uuid[], timestamptz) TO "app_user";
